package api

import "net/http"

func uiHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(uiHTML))
}

const uiHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Helios Console</title>
<style>
:root{color-scheme:dark;--bg:#08111f;--card:#101b31;--card2:#15223b;--line:#263750;--text:#e6edf7;--muted:#8ea0bc;--brand:#7dd3fc;--good:#34d399;--bad:#fb7185;--warn:#fbbf24}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,rgba(56,189,248,.18),transparent 34rem),var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{padding:26px 36px 18px;border-bottom:1px solid var(--line);background:rgba(8,17,31,.82);position:sticky;top:0;z-index:2;backdrop-filter:blur(10px)}h1{margin:0;font-size:36px;letter-spacing:-.04em}h2{margin:0 0 12px;font-size:16px}.sub,.muted{color:var(--muted)}main{display:grid;grid-template-columns:390px minmax(0,1fr);gap:18px;padding:18px 36px 36px}.stack{display:grid;gap:14px;align-content:start}section{background:linear-gradient(180deg,rgba(255,255,255,.04),rgba(255,255,255,.01)),var(--card);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 18px 45px rgba(0,0,0,.28)}label{display:grid;gap:6px;color:var(--muted);font-weight:700}input,textarea,select,button{border:1px solid var(--line);border-radius:12px;background:#0c1528;color:var(--text);padding:10px 12px;font:inherit}textarea{min-height:90px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}button{cursor:pointer;font-weight:800}button.primary{background:linear-gradient(180deg,var(--brand),#38bdf8);color:#03111f;border-color:transparent}button.secondary{background:var(--card2)}button.danger{background:rgba(251,113,133,.13);border-color:rgba(251,113,133,.45);color:#fecdd3}button:disabled{opacity:.55;cursor:not-allowed}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.fit{flex:0 0 auto}.check{display:flex;align-items:center;gap:8px;color:var(--text)}.check input{width:auto}.status{min-height:38px;white-space:pre-wrap;padding:10px 12px;border-radius:12px;background:rgba(125,211,252,.08);border:1px solid rgba(125,211,252,.2);color:#bae6fd}.status.good{background:rgba(52,211,153,.1);border-color:rgba(52,211,153,.25);color:#bbf7d0}.status.bad{background:rgba(251,113,133,.1);border-color:rgba(251,113,133,.25);color:#fecdd3}table{width:100%;border-collapse:collapse}th,td{padding:10px 9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.06em;background:rgba(255,255,255,.03)}tr.case-row{cursor:pointer}tr.case-row:hover{background:rgba(125,211,252,.07)}.pill{display:inline-flex;border-radius:999px;padding:3px 8px;font-size:12px;font-weight:900;border:1px solid var(--line);background:var(--card2)}.queued,.partial,.unverified{color:#fde68a;border-color:rgba(251,191,36,.36)}.running{color:#bae6fd;border-color:rgba(56,189,248,.36)}.done,.handed-off,.verified{color:#bbf7d0;border-color:rgba(52,211,153,.36)}.failed,.engine_error{color:#fecdd3;border-color:rgba(251,113,133,.36)}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;word-break:break-all}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.kv{padding:10px;border:1px solid var(--line);border-radius:12px;background:rgba(12,21,40,.68)}.kv b{display:block;color:var(--muted);font-size:12px;margin-bottom:4px}pre{margin:0;overflow:auto;max-height:320px;background:#050a14;border:1px solid var(--line);border-radius:12px;padding:12px}.split{display:grid;grid-template-columns:1fr 1fr;gap:14px}h3{margin:18px 0 8px;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}@media(max-width:980px){main,.grid,.split{grid-template-columns:1fr}header{position:static}}
</style>
</head>
<body>
<header><h1>Helios Console</h1><div class="sub">Submit Lumos analysis cases, watch queue progress, and inspect results from the browser.</div></header>
<main>
<div class="stack">
<section><h2>Connection</h2><label>Bearer token<input id="token" type="password" autocomplete="off" placeholder="HELIOS_API_TOKEN"></label><div class="row" style="margin-top:10px"><button class="secondary" id="saveToken" type="button">Save token</button><button class="secondary" id="checkHealth" type="button">Check health</button></div><p class="muted">Stored only in browser localStorage. API calls use Authorization: Bearer.</p></section>
<section><h2>Run analysis</h2><form id="submitForm" class="stack"><div class="row"><label>Chain<input id="chain" value="ethereum" required></label><label class="fit check" style="margin-top:24px"><input id="forceRerun" type="checkbox"> Force rerun</label></div><label>Transaction hash<input id="txHash" placeholder="0x...64 hex chars" required></label><label>Source<input id="source" placeholder="manual-ui"></label><label>Metadata JSON<textarea id="metadata" spellcheck="false">{"submitted_by":"helios-ui"}</textarea></label><button class="primary" type="submit">Submit case</button></form></section>
<section><h2>Status</h2><div id="status" class="status">Ready.</div></section>
</div>
<div class="stack">
<section><div class="row"><h2 style="flex:2">Cases</h2><select id="stateFilter" class="fit"><option value="">All states</option><option>queued</option><option>running</option><option>done</option><option>handed-off</option><option>failed</option></select><button class="secondary fit" id="refreshCases" type="button">Refresh</button><label class="fit check"><input id="autoRefresh" type="checkbox" checked> Auto</label></div><div style="overflow:auto"><table><thead><tr><th>State</th><th>Outcome</th><th>Chain / tx</th><th>Attempt</th><th>Handoff</th><th>Updated</th></tr></thead><tbody id="casesBody"><tr><td colspan="6" class="muted">No cases loaded yet.</td></tr></tbody></table></div></section>
<section><div class="row"><h2 style="flex:2">Case detail</h2><button class="danger fit" id="retryHandoff" type="button" disabled>Retry handoff</button></div><div id="caseDetail" class="muted">Select a case from the table.</div></section>
</div>
</main>
<script>
(function(){
var $=function(id){return document.getElementById(id)};
var e={token:$("token"),saveToken:$("saveToken"),checkHealth:$("checkHealth"),form:$("submitForm"),chain:$("chain"),tx:$("txHash"),source:$("source"),metadata:$("metadata"),force:$("forceRerun"),status:$("status"),refresh:$("refreshCases"),auto:$("autoRefresh"),filter:$("stateFilter"),body:$("casesBody"),detail:$("caseDetail"),retry:$("retryHandoff")};
var selected=""; e.token.value=localStorage.getItem("helios.apiToken")||""; e.source.value=localStorage.getItem("helios.defaultSource")||"manual-ui";
function status(msg,kind){e.status.textContent=msg;e.status.className="status"+(kind?" "+kind:"")}
function tok(){return e.token.value.trim()}
function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]})}
function pretty(v){if(v==null||v==="")return "-";if(typeof v==="string"){try{return JSON.stringify(JSON.parse(v),null,2)}catch(_){return v}}return JSON.stringify(v,null,2)}
function auth(extra){var t=tok();if(!t)throw new Error("Set HELIOS_API_TOKEN first.");var h={Authorization:"Bearer "+t};extra=extra||{};Object.keys(extra).forEach(function(k){h[k]=extra[k]});return h}
function api(path,opt){opt=opt||{};opt.headers=auth(opt.headers);return fetch(path,opt).then(function(r){return r.text().then(function(t){var d=null;if(t){try{d=JSON.parse(t)}catch(_){d=t}}if(!r.ok){var err=new Error(d&&d.message?d.message:r.status+" "+r.statusText);err.data=d;throw err}return d})})}
function pill(v){v=v||"-";return "<span class=\"pill "+esc(v)+"\">"+esc(v)+"</span>"}
function time(v){if(!v)return "-";var d=new Date(v);return isNaN(d.getTime())?v:d.toLocaleString()}
function kv(k,v,mono){return "<div class=\"kv\"><b>"+esc(k)+"</b><span class=\""+(mono?"mono":"")+"\">"+esc(v==null||v===""?"-":v)+"</span></div>"}
function renderCases(items){if(!items||!items.length){e.body.innerHTML="<tr><td colspan=\"6\" class=\"muted\">No cases found.</td></tr>";return}e.body.innerHTML=items.map(function(c){var tx=c.tx_hash||"",short=tx.length>22?tx.slice(0,12)+"..."+tx.slice(-8):tx;return "<tr class=\"case-row\" data-case=\""+esc(c.case_id)+"\"><td>"+pill(c.state)+"</td><td>"+pill(c.outcome||c.failure_kind||"-")+"</td><td><div>"+esc(c.chain)+"</div><div class=\"mono\" title=\""+esc(tx)+"\">"+esc(short)+"</div></td><td>"+esc(c.attempt_number)+"</td><td>"+pill(c.handoff_status)+"</td><td>"+esc(time(c.updated_at))+"</td></tr>"}).join("");Array.prototype.forEach.call(document.querySelectorAll("tr.case-row"),function(tr){tr.onclick=function(){loadCase(tr.getAttribute("data-case"))}})}
function loadCases(quiet){var q=new URLSearchParams({limit:"50"});if(e.filter.value)q.set("state",e.filter.value);return api("/cases?"+q.toString()).then(function(d){renderCases(d.items||[]);if(!quiet)status("Loaded "+(d.items||[]).length+" of "+d.total+" cases.","good");if(selected)loadCase(selected,true)}).catch(function(err){if(!quiet)status("Case load failed: "+err.message+"\n"+pretty(err.data),"bad")})}
function events(items){if(!items||!items.length)return "<div class=\"muted\">No events.</div>";return "<div style=\"overflow:auto\"><table><thead><tr><th>Type</th><th>Transition</th><th>At</th><th>Payload</th></tr></thead><tbody>"+items.map(function(x){return "<tr><td>"+esc(x.event_type)+"</td><td>"+esc((x.from_state||"-")+" -> "+(x.to_state||"-"))+"</td><td>"+esc(time(x.occurred_at))+"</td><td><pre>"+esc(pretty(x.payload))+"</pre></td></tr>"}).join("")+"</tbody></table></div>"}
function attempts(items,kind){if(!items||!items.length)return "<div class=\"muted\">No "+esc(kind)+" attempts.</div>";if(kind==="handoff")return "<div style=\"overflow:auto\"><table><thead><tr><th>Result</th><th>URL</th><th>Status</th><th>At</th><th>Error</th></tr></thead><tbody>"+items.map(function(a){return "<tr><td>"+pill(a.result)+"</td><td class=\"mono\">"+esc(a.target_url)+"</td><td>"+esc(a.http_status||"-")+"</td><td>"+esc(time(a.attempted_at))+"</td><td>"+esc(a.error||"")+"</td></tr>"}).join("")+"</tbody></table></div>";return "<div style=\"overflow:auto\"><table><thead><tr><th>Result</th><th>Channel</th><th>Event</th><th>At</th><th>Error</th></tr></thead><tbody>"+items.map(function(a){return "<tr><td>"+pill(a.result)+"</td><td>"+esc(a.channel)+"</td><td>"+esc(a.event)+"</td><td>"+esc(time(a.attempted_at))+"</td><td>"+esc(a.error||"")+"</td></tr>"}).join("")+"</tbody></table></div>"}
function loadCase(id,quiet){if(!id)return;selected=id;return api("/cases/"+encodeURIComponent(id)).then(function(c){e.retry.disabled=!(c.state==="done"&&c.handoff_status==="failed");e.detail.innerHTML="<div class=\"grid\">"+kv("Case ID",c.case_id,true)+kv("State",c.state)+kv("Outcome",c.outcome||c.failure_kind||"-")+kv("Handoff",c.handoff_status)+kv("Chain",c.chain)+kv("Tx hash",c.tx_hash,true)+kv("Output root",c.output_root||"-",true)+kv("Summary JSON",c.summary_json_path||"-",true)+kv("Attempt",c.attempt_number)+kv("Notification",c.notification_status)+"</div><h3>Metadata</h3><pre>"+esc(pretty(c.metadata))+"</pre><h3>Events</h3>"+events(c.case_events)+"<div class=\"split\"><div><h3>Handoff attempts</h3>"+attempts(c.handoff_attempts,"handoff")+"</div><div><h3>Notification attempts</h3>"+attempts(c.notification_attempts,"notification")+"</div></div>";if(!quiet)status("Loaded case "+c.case_id,"good")}).catch(function(err){e.detail.innerHTML="<div class=\"status bad\">"+esc(err.message)+"</div>";if(!quiet)status("Case detail failed: "+err.message+"\n"+pretty(err.data),"bad")})}
e.saveToken.onclick=function(){localStorage.setItem("helios.apiToken",tok());localStorage.setItem("helios.defaultSource",e.source.value.trim()||"manual-ui");status("Saved token in this browser.","good")};
e.checkHealth.onclick=function(){fetch("/healthz").then(function(r){return r.json()}).then(function(d){status("Helios health: "+pretty(d),"good")}).catch(function(err){status("Health failed: "+err.message,"bad")})};
e.form.onsubmit=function(ev){ev.preventDefault();var body={chain:e.chain.value.trim(),tx_hash:e.tx.value.trim(),force_rerun:e.force.checked};if(e.source.value.trim())body.source=e.source.value.trim();if(e.metadata.value.trim()){try{body.metadata=JSON.parse(e.metadata.value)}catch(err){status("Metadata JSON invalid: "+err.message,"bad");return}}status("Submitting analysis case...");api("/cases",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}).then(function(d){status("Submitted "+d.case_id+" ("+d.status+").","good");selected=d.case_id;return loadCases(true).then(function(){return loadCase(d.case_id,true)})}).catch(function(err){status("Submit failed: "+err.message+"\n"+pretty(err.data),"bad")})};
e.refresh.onclick=function(){loadCases(false)};e.filter.onchange=function(){loadCases(false)};e.retry.onclick=function(){if(!selected)return;api("/cases/"+encodeURIComponent(selected)+"/retry-handoff",{method:"POST"}).then(function(d){status("Retry requested:\n"+pretty(d),"good");loadCase(selected,true)}).catch(function(err){status("Retry failed: "+err.message+"\n"+pretty(err.data),"bad")})};
setInterval(function(){if(e.auto.checked&&tok())loadCases(true)},5000);if(tok())loadCases(true);
})();
</script>
</body>
</html>`
